# 第 6 批：卦 45-53（萃、升、困、井、革、鼎、震、艮、渐）

HEXAGRAMS = {
  "45": {"zh": "萃卦下坤上兑，聚众。它讲的是聚人的道理——萃就是聚，聚得正才得到众人。", "en": "Cui is yielding below, joy above — gathering people. Cui means to gather; gathering rightly is how you win the crowd.", "ja": "萃は下が坤、上が兑。衆を集める。集めることを表す——萃とは集まりであり、正しく集めれば衆を得る。"},
  "46": {"zh": "升卦下巽上坤，积小成高。它讲的是上升——被认可就大成，靠积累而不骤然。", "en": "Sheng is compliance below, earth above — piling small into high. It's about rising: trusted, you grow great — accumulating, not leaping.", "ja": "升は下が巽、上が坤。小さく積んで高くなる。上昇を表す——認められれば大きく、積もって急がない。"},
  "47": {"zh": "困卦下坎上兑，困穷。它讲身处困境——困而不失其所亨，舍命遂志，困也能通达。", "en": "Kun is danger below, joy above — destitution. It's about being in straits: in difficulty don't lose what flows; give up life to fulfill your aim — even difficulty opens through.", "ja": "困は下が坎、上が兑。行き詰まり。困窮を表す——困っても亨る所を失わず、命を捨てて志を遂げれば、困も通じる。"},
  "48": {"zh": "井卦下巽上坎，井养不穷。它讲养人——井就是养，养之不尽，这是井的德。", "en": "Jing is compliance below, water above — the well nourishes endlessly. It's about nourishing others: Jing means nourishment, inexhaustible — that's the well's virtue.", "ja": "井は下が巽、上が坎。井が养って尽きない。人を养うことを表す——井とは养いであり、养って穷まない。それが井の徳だ。"},
  "49": {"zh": "革卦下离上兑，变革。它讲变革——革得得当，悔恨就消；水火相克而后能变。", "en": "Ge is clarity below, joy above — revolution. It's about change: change done rightly, regret vanishes. Water and fire overcome each other, then transformation comes.", "ja": "革は下が離、上が兑。変革。変えることを表す——革りが当たれば悔いは消える。水火が相い消して初めて変われる。"},
  "50": {"zh": "鼎卦下巽上离，鼎新。它讲养贤——鼎是国之重宝，虚而能容，接纳四方。", "en": "Ding is compliance below, clarity above — the cauldron renewing. It's about nourishing the worthy: the cauldron is a treasure of the state, empty yet holding, receiving from all directions.", "ja": "鼎は下が巽、上が離。鼎は新たにする。賢者を养うことを表す——鼎は国の宝で、虚しくて容れ、四方を受け入れる。"},
  "51": {"zh": "震卦为雷，重雷。它讲惊惕——雷震惊百里，主祭者却不失匕鬯，惊而后能定。", "en": "Zhen is thunder, thunder doubled. It's about alarm: thunder shakes a hundred miles, yet the host doesn't drop the ladle — startled, then able to settle.", "ja": "震は雷、雷が重なる。驚き戒めることを表す——雷は百里を震わせても、主祭者は匕鬯を落とさない。驚いて後、定まれる。"},
  "52": {"zh": "艮卦为山，重艮。它讲止之道——止于背，知止而后能定，不见其人，便无所争。", "en": "Gen is mountain, mountain doubled. It's the way of stopping: stop at the back; know when to stop and you can settle. Not seeing the person, there's no contention.", "ja": "艮は山、山が重なる。止める道を表す——背で止める。止まることを知って初めて定まる。その人を見なければ、争うこともない。"},
  "53": {"zh": "渐卦下艮上巽，渐进。它讲循序渐进——像鸿雁一步步飞，按顺序而不越级。", "en": "Jian is mountain below, compliance above — gradual advance. It's about proceeding stepwise: like the wild goose flying onward, following the sequence without skipping.", "ja": "漸は下が艮、上が巽。徐々に進む。順を踏んで進むことを表す——雁が少しずつ飛ぶように、順序を守って段を飛ばさない。"},
}

LINES = {
  # 45 萃
  "45-0": {"zh": "你在最底下，是萃的开始，与九四相应却信不终。聚人的关键在信有终——信不终，聚必乱；能前往从正就可免。", "en": "You're at the bottom, the start of Cui — matched with the fourth line but trust doesn't last. Gathering depends on trust enduring. When trust fails, the crowd scatters. Go and follow what's right and you avoid it.", "ja": "一番下にいて、萃の初め。九四に応じるが信が続かない。集めるのは信に終わりがあることが肝心。信が続かなければ集まりは乱れる。正に従って往けば免れる。"},
  "45-1": {"zh": "你在下卦正中，柔顺得正而应九五，等被引才前往。进必要等引，不可自往——诚存于心，薄祭也能通。", "en": "You're at the center of the lower trigram, soft and proper, matched with the fifth line — wait to be led before going. Advancing needs a summons; don't go on your own. With sincerity inside, even a thin offering connects.", "ja": "下卦の中央にいて、柔らかく正しく九五に応じる。導かれてから往く。進むには導きを待つべきで、みずから往いてはならない。誠が内にあれば、薄い祭りでも通じる。"},
  "45-2": {"zh": "你在下卦最上面，不中不正，想聚却没人相应。求聚不得，所以叹息——能从上，则虽吝也可说无过。", "en": "You're at the top of the lower trigram — off-center and improper — wanting to gather but no one joins. Seeking union and failing, you sigh. If you follow those above, though regretful, you can be faultless.", "ja": "下卦の最上部にいて、中も正も外れ、集まろうとして応じる者がない。集められず嘆く。上に従えば、吝ではあるが過ちはないと言える。"},
  "45-3": {"zh": "你在上卦下面，靠近九五，为众所聚而位不当。近君之地、众人所聚，其势可畏——必尽善才能免过。", "en": "You're below the upper trigram, near the fifth line, a magnet for the crowd though out of place. Near the ruler and drawing the crowd, your position is daunting. Only by being fully good can you avoid fault.", "ja": "上卦の下にいて、九五に近く、衆の集まる所だが位が当たらない。君に近く衆が集まるのは、その勢いが恐ろしい。善を尽くして初めて過ちを免れる。"},
  "45-4": {"zh": "你身居尊位，刚健中正，是萃的主爻，有人还没信你。有位而未尽信，就修常久之德——德修，悔自消。", "en": "You're in the place of honor, strong and centered — Cui's main line — yet some don't fully trust you. Having position without full trust, cultivate lasting virtue. Virtue cultivated, regret fades by itself.", "ja": "尊い位にいて、剛中で正しく、萃の主爻となる。まだ信じない者がいる。位があっても信が足りなければ、久しい徳を修める。徳が修まれば悔いは自ずと消える。"},
  "45-5": {"zh": "你到了卦的顶，是萃的终点，求聚不得，忧惧很深。求聚不得而自伤，是情切——知惧不止，故可无过。", "en": "You're at the top of the hexagram, Cui at its end — seeking union and failing, deeply anxious. Seeking and failing, you grieve — deep feeling. Knowing fear and not stopping, you can avoid fault.", "ja": "卦の頂点にいて、萃の終わり。集めようとして得られず、憂え恐れること深い。集められず自らを傷つけるのは情が切なるゆえ。恐れを知ってやまないので、過ちは免れる。"},
  # 46 升
  "46-0": {"zh": "你在最底下，是升的开始，被两个阳爻信任，与之一同上升。升必要有信——上信你，就与之俱进，其升也顺。", "en": "You're at the bottom, the start of Sheng — trusted by two yang lines, rising with them. Rising needs trust. Trusted above, you advance together — your rise is smooth.", "ja": "一番下にいて、升の初め。二つの陽に信じられ、共に上る。升るには信が要る。上に信じられれば共に進み、その昇りは順調だ。"},
  "46-1": {"zh": "你在下卦正中，刚健中正而上应六五，以诚相感。以诚事上，薄礼也能通——中心有孚，不靠文饰。", "en": "You're at the center of the lower trigram, strong and centered, reaching up to the fifth line, responding in sincerity. Serve above with sincerity and even a thin gift connects. Faith at the center needs no ornament.", "ja": "下卦の中央にいて、剛中で上の六五に応じ、誠で感応する。誠で上に仕えれば薄い礼でも通じる。中心の孚は、飾りを借りない。"},
  "46-2": {"zh": "你在下卦最上面，刚正而进，进入无人之邑。其进无阻，如入空城——刚而得正，所以升得顺。", "en": "You're at the top of the lower trigram, strong and upright, advancing into an empty town. Your way is unobstructed, like entering a vacant city. Strong and right, your rise is smooth.", "ja": "下卦の最上部にいて、剛正で進み、人のいない邑に入る。その進みに障害はなく、空の城に入るようだ。剛で正を得たので、昇りは順調だ。"},
  "46-3": {"zh": "你在上卦下面，柔顺得正而近九五，积诚以事上。以诚事上，不求进位——如祭于山，诚在心不在物。", "en": "You're below the upper trigram, soft and proper near the fifth line, heaping sincerity to serve above. Serve with sincerity without seeking advancement — like sacrificing on a mountain, the heart matters, not the gift.", "ja": "上卦の下にいて、柔らかく正しく九五に近く、誠を積んで上に仕える。誠で仕えて位を求めない。山に祭るようなもので、誠は心にあり物にあるのではない。"},
  "46-4": {"zh": "你在尊位，柔和中正而下应九二，升得有序。升必有顺序，如登阶有级——柔中而任贤，所以升得安。", "en": "You're in the place of honor, soft and centered, reaching down to the second line — rising in order. Rising must have sequence, like steps on a stair. Soft-centered and appointing worthies, your rise is secure.", "ja": "尊い位にいて、柔らかく中を得て九二に応じ、昇りに順序がある。升るには順序が要る——段を登るようなもの。柔中で賢者を任せるので、昇りは安い。"},
  "46-5": {"zh": "你到了卦的顶，是升的终点，升而不已，心不明。升极而不知止，是冥——只有不息之正可以救其失。", "en": "You're at the top of the hexagram, Sheng at its end — rising without end, your mind dark. Rising to the extreme without knowing to stop is blindness. Only unceasing rightness can save you.", "ja": "卦の頂点にいて、升の終わり。昇り続けて心が明らかでない。昇りの極で止まることを知らぬのは冥い。不息の正だけがその失いを救える。"},
  # 47 困
  "47-0": {"zh": "你在最底下，是困的开始，困坐于下不得进。困在下又无依，入得很深——柔而不能自拔，所以久不见用。", "en": "You're at the bottom, the start of Kun — stuck below, unable to advance. Stuck low with nothing to lean on, you sink deep. Soft and unable to free yourself, long unused.", "ja": "一番下にいて、困の初め。下に座し込んで進めない。下にあって頼るものなく、深く入る。柔で自ら抜けられず、久しく用いられない。"},
  "47-1": {"zh": "你在下卦正中，刚健中正却困于供养丰厚。困不在贫而在过——有其德则荣禄自来，以诚处之可免。", "en": "You're at the center of the lower trigram, strong and centered, yet trapped by rich provisions. The trap isn't poverty but excess. With virtue, honor comes on its own; meet it with sincerity and avoid harm.", "ja": "下卦の中央にいて、剛中で養うものの豊かさに困る。困いは貧ではなく過ぎにある。徳があれば栄禄は自ら来る。誠をもって処せば免れられる。"},
  "47-2": {"zh": "你在下卦最上面，不中不正，前后都是刚，无处容身。进退皆困、内又无归，是道之穷——柔而不正，故至于此。", "en": "You're at the top of the lower trigram — off-center and improper — rigid before and behind, with nowhere to stand. Stuck either way with no home within, your way is exhausted. Soft and improper, you came to this.", "ja": "下卦の最上部にいて、中も正も外れ、前後とも剛で容れる所がない。進んでも引いても困り、内に帰る所もない——道の穷まりだ。柔で正しくないので、ここに至った。"},
  "47-3": {"zh": "你在上卦下面，与初六正应，被九二隔开。困于隔而不能速，然其应自在——徐而不已，故能有终。", "en": "You're below the upper trigram, properly matched with the first line but blocked by the second. Blocked and slowed, yet the bond remains. Slow and unceasing, you reach a good end.", "ja": "上卦の下にいて、初六と正しく応じるが九二に隔てられる。隔てられて急げないが、応えは自ずとある。徐ろにやまないので、良い終わりを得る。"},
  "47-4": {"zh": "你身居尊位，刚健中正却困于上下之阴。困于人而不得行志，就徐徐图之——以诚处之，悦自至。", "en": "You're in the place of honor, strong and centered, trapped by the yin above and below. Blocked by people and unable to act, proceed slowly. Meet it with sincerity and relief comes.", "ja": "尊い位にいて、剛中で上下の陰に困る。人に阻まれて志を行えなければ、徐ろに計る。誠をもって処すれば、悦びは自ら来る。"},
  "47-5": {"zh": "你到了卦的顶，是困的终点，缠绵不安不能自定。困极则动而悔生——能悔其所为而改，前往可有得。", "en": "You're at the top of the hexagram, Kun at its end — tangled, unsettled, unable to settle. At extremity you stir and regret arises. If you regret your acts and change, going forward can gain.", "ja": "卦の頂点にいて、困の終わり。まとわりついて安まらず、自ら定まれない。困り極まれば動いて悔いが生じる。自分の所为を悔いて改めれば、往いて得る所がある。"},
  # 48 井
  "48-0": {"zh": "你在最底下，是井底，泥污而不为人用。在下而无用于世，是泥井——德不加修，就没人来取。", "en": "You're at the bottom, the mud at the well's base — dirty and unusable. Low and useless to the world, a muddy well. If virtue isn't cultivated, no one draws from you.", "ja": "一番下にいて、井の底。泥に汚れて人に用いられない。下にいて世に役立たぬのは泥の井。徳を修めなければ、人は汲みに来ない。"},
  "48-1": {"zh": "你在下卦正中，刚中而无上应，用只及于小。有才无援，所施就窄——如井水下注，仅及小鱼。", "en": "You're at the center of the lower trigram, strong but without a match above — your use reaches only small things. Talent without support gives narrow reach. Like well-water flowing down, it reaches only small fry.", "ja": "下卦の中央にいて、剛中で上の応えがなく、用は小さなものに及ぶ。才があっても助けがなければ、及ぼす範囲は狭い。井の水が下へ流れ、小さな魚に届くばかりだ。"},
  "48-2": {"zh": "你在下卦最上面，刚正而井已洁，还未被人用。已治而未见用，是可恻——遇明主，就与之共受其福。", "en": "You're at the top of the lower trigram, strong and upright — the well is clean but not yet used. Cleansed yet unused is pitiable. Meet a discerning one and you'll share the blessing.", "ja": "下卦の最上部にいて、剛正で井はすでに清いが、まだ人に用いられていない。治っていて用いられぬのは哀れだ。明らかな者に巡り合えば、共にその福を受ける。"},
  "48-3": {"zh": "你在上卦下面，柔顺得正而修井之壁，功在内。修内不求外，是自守——但能无过，未见其及人。", "en": "You're below the upper trigram, soft and proper, lining the well's wall — the work is inside. Cultivating within without seeking outside is self-keeping. You avoid fault, but no wide benefit is seen.", "ja": "上卦の下にいて、柔らかく正しく井の甃を修める。功は内にある。内を修めて外を求めないのは自守だ。過ちはないが、人に及ぶところはまだ見えない。"},
  "48-4": {"zh": "你身居尊位，刚中是井之清者，可以食人。有德有位，泽就及人——中正之泉，人所共汲。", "en": "You're in the place of honor, strong and centered — the well's clear water, able to feed people. Virtue with position extends your grace. A centered, upright spring is drawn by all.", "ja": "尊い位にいて、剛中で井の澄んだ水となる。人を食せる。徳と位があれば恵みは人に及ぶ。中正の泉は、人々がともに汲む。"},
  "48-5": {"zh": "你到了卦的顶，是井的终点，其功已成而不自遮蔽。有泽而公之于人，不私有——信之所及，其用无穷。", "en": "You're at the top of the hexagram, Jing at its end — the work done and not hiding it. Having grace, share it openly, don't keep it private. Where trust reaches, the use is endless.", "ja": "卦の頂点にいて、井の終わり。その功は成り、自ら覆い隠さない。恵みを人に公にし、私有しない。信の及ぶところ、その用は穷まない。"},
  # 49 革
  "49-0": {"zh": "你在最底下，是革的开始，时未可革，用中顺固守。革不可急——时未至就固守常道，不可以刚逞强。", "en": "You're at the bottom, the start of Ge — the time isn't right, hold fast with centered compliance. Change can't be hasty. Before the time, keep the constant way; don't flaunt your strength.", "ja": "一番下にいて、革の初め。まだ革める時でない。中順で固く守る。革は急げない。時が来ねば常道を守り、剛で強がってはならない。"},
  "49-1": {"zh": "你在下卦正中，柔顺得正而上应九五，时可革而后革。革必待其时——中顺而应上，所以行无过。", "en": "You're at the center of the lower trigram, soft and proper, matched above with the fifth line — change when the time allows. Change must wait for its day. Centered, compliant, matched above, you act without fault.", "ja": "下卦の中央にいて、柔らかく正しく上の九五に応じる。時が革めてよいと決まってから革める。革はその時を待つ。中順で上に応じるので、行いに過ちはない。"},
  "49-2": {"zh": "你在下卦最上面，过刚而革，躁则危、审则可。革议反复三次才定，是慎之至——有其诚则人不疑。", "en": "You're at the top of the lower trigram — overly rigid in change — rash is dangerous, deliberate works. Reaching three consultations before deciding is utmost care. With sincerity, no one doubts.", "ja": "下卦の最上部にいて、剛が過ぎて革める。躁れば危く、審えればよい。革の議論を三度繰り返して初めて決めるのは、慎みの極だ。誠があれば人は疑わない。"},
  "49-3": {"zh": "你在上卦下面，刚而居柔，担当变革之任。有其诚就可以改其命——刚柔相济，故事可成而悔亡。", "en": "You're below the upper trigram, strong in a soft place — bearing the charge of change. With sincerity you can reform the decree. Strength and softness aid each other, so the task succeeds and regret vanishes.", "ja": "上卦の下にいて、剛で柔の位にあり、変革の任を負う。誠があればその命を改められる。剛柔が助け合うので、事は成って悔いは消える。"},
  "49-4": {"zh": "你身居尊位，刚健中正，是革的主爻，其变显著。大人之变，文采炳然——不待问而人自信，是诚之至。", "en": "You're in the place of honor, strong and centered — Ge's main line — your change conspicuous. A great one's change is brilliantly patterned. Without being asked, people trust you: utmost sincerity.", "ja": "尊い位にいて、剛中で正しく、革の主爻。その変わりは著しい。大人の変わりは文が炳然としている。問わずとも人が信じる——誠の極だ。"},
  "49-5": {"zh": "你到了卦的顶，是革的终点，君子变其文，小人变其貌。革之既成，不可以更进——守其成而已，往则过。", "en": "You're at the top of the hexagram, Ge at its end — the gentleman changes his pattern, the small man changes his face. Once change is complete, don't push further. Just keep the achievement; going on is excess.", "ja": "卦の頂点にいて、革の終わり。君子はその文を変え、小人はその貌を変える。革りが成ったら、さらに進んではならない。その成りを守るだけだ。往けば過ちだ。"},
  # 50 鼎
  "50-0": {"zh": "你在最底下，是鼎的开始，颠其趾以倒出陈积之污。去旧恶，虽颠也可以——因贱得贵，故无过。", "en": "You're at the bottom, the start of Ding — tipping the legs to pour out old sediment. Removing old filth, even tipping is fine. Through the low you gain the noble, so no fault.", "ja": "一番下にいて、鼎の初め。足を返して古く溜まった汚れを出す。古い悪を除くなら、ひっくり返してもよい。賤しいところから貴いものを得るので、過ちはない。"},
  "50-1": {"zh": "你在下卦正中，刚中而有其实，为六五所应。有德者，虽被嫉也不能近——刚中自守，其道可行。", "en": "You're at the center of the lower trigram, strong and centered with real substance — matched with the sixth line above. One with virtue, though envied, can't be approached. Strong-centered and self-keeping, your way goes.", "ja": "下卦の中央にいて、剛中で実があり、六五に応じられる。徳ある者は、嫉まれても近づけない。剛中を守るので、その道は行かれる。"},
  "50-2": {"zh": "你在下卦最上面，过刚而不中，其行有阻。刚过则与五不合，故行塞——能自反以和之，终有得。", "en": "You're at the top of the lower trigram — overly rigid, off-center — your movement blocked. Too rigid, you don't match the fifth line, so you're stopped. Turn back and harmonize, and in the end you gain.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、その行いに阻むものがある。剛が過ぎて五と合わないので塞がる。みずから返って和らげれば、終わりに得る所がある。"},
  "50-3": {"zh": "你在上卦下面，不中不正，任重而才不胜。任非其才，就败人之事——德薄位尊，是自取其败。", "en": "You're below the upper trigram — off-center and improper — a heavy charge beyond your ability. Wrong person for the role ruins the work. Thin virtue, high station: you bring about your own downfall.", "ja": "上卦の下にいて、中も正も外れ、重い任を負うが才が及ばない。任が才に非ずば人の事を敗る。徳が薄く位が尊いのは、自らその敗れを招くものだ。"},
  "50-4": {"zh": "你身居尊位，柔中而下应九二，以中受刚。以柔中之德受刚中之辅，其举也重——守正则可以任。", "en": "You're in the place of honor, soft and centered, reaching down to the second line — receiving strength with the mean. With soft-centered virtue receiving a strong-centered helper, your support is solid. Keep rightness and you can bear it.", "ja": "尊い位にいて、柔らかく中を得て九二に応じ、中で剛を受ける。柔中の徳で剛中の補佐を受ければ、その支えは重い。正を守れば任せられる。"},
  "50-5": {"zh": "你到了卦的顶，是鼎的终点，刚而居柔，其德如玉。刚而能柔，温润不可犯——鼎道之成，故用无不利。", "en": "You're at the top of the hexagram, Ding at its end — strong in a soft place, your virtue like jade. Strong yet soft, warm and not to be violated. Ding's way fulfilled, so nothing is unfavorable.", "ja": "卦の頂点にいて、鼎の終わり。剛で柔の位にあり、その徳は玉のよう。剛で柔を作え、温潤で犯せない。鼎の道が成ったので、用いるに不利なことはない。"},
  # 51 震
  "51-0": {"zh": "你在最底下，是震的开始，惧而后安，其惧有则。先惧后安，是知畏——畏则可无患，故笑言有节。", "en": "You're at the bottom, the start of Zhen — fearful then secure, with measure in your fear. Fear first, security after: that's knowing awe. Awe avoids trouble, so laughter and words have measure.", "ja": "一番下にいて、震の初め。恐れて後安んじ、その恐れには節度がある。先に恐れて後安ぶのは、畏ることを知る者。畏れば患いを免れ、笑い言葉にも節度がある。"},
  "51-1": {"zh": "你在下卦正中，柔顺得正而遇震来，丧其所守。所失的是外物，不必追——守其中正，久则自复。", "en": "You're at the center of the lower trigram, soft and proper, meeting thunder and losing what you held. What's lost is a thing — don't chase it. Keep your center and rightness; in time it returns.", "ja": "下卦の中央にいて、柔らかく正しく震の来るに遭い、守るものを失う。失ったのは物なので追う必要はない。中正を守れば、久しくして自ら戻る。"},
  "51-2": {"zh": "你在下卦最上面，不中不正，惧而自失，行则可免。不安而能行，就可无灾——惧而能改，是可教者。", "en": "You're at the top of the lower trigram — off-center and improper — fearful and self-lost; moving can save you. Uneasy yet able to act avoids disaster. Fearful and able to change: you're teachable.", "ja": "下卦の最上部にいて、中も正も外れ、恐れて自らを失う。行けば免れられる。安まなくても行えるなら災いはない。恐れて改められるのは、教えられる者だ。"},
  "51-3": {"zh": "你在上卦下面，刚而居柔，陷在二阴之间。刚而不能自奋，陷于阴中——有其刚而无其用，是滞。", "en": "You're below the upper trigram, strong in a soft place, trapped between two yin lines. Strong but unable to rouse yourself, stuck among yin. Having strength without using it is stagnation.", "ja": "上卦の下にいて、剛で柔の位にあり、二つの陰の間に陷る。剛で自ら奮えず、陰の中に沈む。剛があって用いられないのは、滞りだ。"},
  "51-4": {"zh": "你在尊位，柔和中正而处震，往来皆危却无所丧。守其中则虽危不失——有其事而不失守，是能危者。", "en": "You're in the place of honor, soft and centered amidst thunder — danger coming and going, yet nothing lost. Hold your center and though endangered you don't lose. Handling danger without losing your grip: that's meeting danger well.", "ja": "尊い位にいて、柔らかく中を得て震に処する。往来とも危ういが失うものがない。中を守れば危くても失わない。事があっても守りを失わない——危うさに堪える者だ。"},
  "51-5": {"zh": "你到了卦的顶，是震的终点，其惧已极，其视不定。惧极则不可以行——能在未及身时先戒，就可免。", "en": "You're at the top of the hexagram, Zhen at its end — fear at its peak, your gaze unsteady. At extreme fear you can't act. If you take warning before it reaches you, you can avoid it.", "ja": "卦の頂点にいて、震の終わり。恐れは極まり、見る目は定まらない。恐り極まれば行けない。まだ身に及ばぬうちに戒めれば、免れられる。"},
  # 52 艮
  "52-0": {"zh": "你在最底下，是止的开始，在动之初就止住。止于未动，其止也易——能常守，故可无过。", "en": "You're at the bottom, the start of Gen — stopping at the first stir. Stop before moving and stopping is easy. Keep it constant and you avoid fault.", "ja": "一番下にいて、止めの初め。動きの初めに止める。まだ動かぬうちに止めれば、その止めは容易。常に守れれば、過ちはない。"},
  "52-1": {"zh": "你在下卦正中，柔顺得正，却止于所随者。己虽止而不能止其所随，故心不安——止于己而未及人。", "en": "You're at the center of the lower trigram, soft and proper, but stopping at what you follow. You stop yet can't stop those around you, so your heart is uneasy. Stopping yourself but not reaching others.", "ja": "下卦の中央にいて、柔らかく正しく、従う者どころに止まっている。自分は止めても随う者を止められず、心は安まない。己に止まって人に及ばずだ。"},
  "52-2": {"zh": "你在下卦最上面，过刚而不中，止得太甚。止而不得其所，反以自伤——刚而过者，其心不安。", "en": "You're at the top of the lower trigram — overly rigid, off-center — stopping too hard. Stopping in the wrong place harms you instead. Rigid and excessive, your heart is uneasy.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、止めが甚だすぎる。止める所を得なければ、かえって自らを傷つける。剛で過ぎた者は、心が安まない。"},
  "52-3": {"zh": "你在上卦下面，柔顺得正而止于其身，不向外施。止于身而不妄动，是本分——能自止，故可无过。", "en": "You're below the upper trigram, soft and proper, stopping at your own body, not acting outwardly. Stopping at yourself without rash motion is your part. Self-stopping avoids fault.", "ja": "上卦の下にいて、柔らかく正しく身に止まり、外へ施さない。身に止まって妄りに動かないのが本分だ。自ら止められるので、過ちはない。"},
  "52-4": {"zh": "你在尊位，柔和中正而止于其言，其言有序。止其言则言不妄发——柔中而出之以序，故悔可消。", "en": "You're in the place of honor, soft and centered, stopping at your words — your words have order. Restraining speech keeps it from rashness. Soft-centered and expressed in order, regret can vanish.", "ja": "尊い位にいて、柔らかく中を得て言葉に止まる。その言葉には順序がある。言葉を止めれば妄りに発しない。柔中で秩序をもって出せば、悔いは消える。"},
  "52-5": {"zh": "你到了卦的顶，是止的终点，敦厚于止而不已。止极而能敦厚以终，是止道之成——久而不变，故得其终。", "en": "You're at the top of the hexagram, Gen at its end — generous in stopping without end. At the peak of stopping, ending generously is the way fulfilled. Long unchanging, you reach a good end.", "ja": "卦の頂点にいて、止めの終わり。敦く止めてやまない。止めの極で敦厚に終えられるのは、止めの道の成就だ。久しく変わらぬので、良い終わりを得る。"},
  # 53 渐
  "53-0": {"zh": "你在最底下，是渐的开始，进于水涯，其进尚微。进之始，位未安——虽有小言，是常，不足为患。", "en": "You're at the bottom, the start of Jian — advancing at the water's edge, still slight. At the start your place isn't settled. Though there's a little talk, that's normal and no real trouble.", "ja": "一番下にいて、漸の初め。水辺へ進むが、その進みはまだ微か。進み始めは位が安まらない。小さな噂があっても常のことであり、患いには足りない。"},
  "53-1": {"zh": "你在下卦正中，柔顺得正而上应九五，进得其所安。进得其安，可以从容自养——中正而应，故其乐也和。", "en": "You're at the center of the lower trigram, soft and proper, matched with the fifth line above — advancing to a settled place. Advancing to ease, you can nurture yourself calmly. Centered, upright, matched — your joy is harmonious.", "ja": "下卦の中央にいて、柔らかく正しく九五に応じ、進んで安きを得る。進んで安ければ、从容に自分を養える。中正に応えるので、その喜びは和やかだ。"},
  "53-2": {"zh": "你在下卦最上面，过刚而不中，失其所安而妄进。刚而过则失所守，往而不复——惟用之御外，可以得其正。", "en": "You're at the top of the lower trigram — overly rigid, off-center — leaving ease to rush ahead. Too rigid loses your grip; you go and don't return. Only using it against outside danger keeps you right.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、安きを失って妄りに進む。剛が過ぎれば守るものを失い、行って返らない。外を防ぐのに用いて初めて正を得られる。"},
  "53-3": {"zh": "你在上卦下面，柔顺得正而进于不安之地。所处不安而能得所依，就可以安——柔顺得正，故可免。", "en": "You're below the upper trigram, soft and proper, advancing into an uneasy place. Unsettled yet finding support, you can be at ease. Soft and proper, you avoid harm.", "ja": "上卦の下にいて、柔らかく正しく、安からぬ場所へ進む。所が安まなくても頼る所を得れば安んじられる。柔顺で正を得たので、免れられる。"},
  "53-4": {"zh": "你在尊位，刚中而下应六二，被三四所隔。中道之合，虽隔终不可夺——久则自通，是正之胜。", "en": "You're in the place of honor, strong and centered, reaching down to the second line but blocked by the third and fourth. A rightful union, though blocked, can't be taken away. In time it opens — rightness wins.", "ja": "尊い位にいて、剛中で六二に応じるが三・四に隔てられる。中道の合いは、隔てられても奪えない。久しければ自ずと通じる——正の勝ちだ。"},
  "53-5": {"zh": "你到了卦的顶，是渐的终点，超然于外，其仪可法。进之极而不累于位，可为法者在其仪——志在高远，不徒进也。", "en": "You're at the top of the hexagram, Jian at its end — rising above, your bearing exemplary. At advance's peak, unburdened by station, what sets an example is your bearing. The aim is lofty, not mere advancement.", "ja": "卦の頂点にいて、漸の終わり。超然として外にあり、その振る舞いは手本となる。進みの極で位に縛られず、手本となるのはその儀だ。志は高遠にあり、ただ進むのではない。"},
}
